serverCode:
while ( $record = $button->getNextSelectedRecord() ) {
    $temaParaExcluir = $record["tema"];
    if ($temaParaExcluir == 'Mapas Base') {
        continue;
    }
    if (!empty($temaParaExcluir)) {
        $sqlDeletaPacotes = "DELETE FROM app.t_pack 
                             WHERE pack IN (
                                 SELECT pack FROM app.t_tema_pack WHERE tema = '" . $temaParaExcluir . "'
                             )";
        DB::Exec($sqlDeletaPacotes);
        $sqlDeletaRelacao = "DELETE FROM app.t_tema_pack WHERE tema = '" . $temaParaExcluir . "'";
        DB::Exec($sqlDeletaRelacao);
        $sqlDeletaTemaPrincipal = "DELETE FROM app.t_tema WHERE tema = '" . $temaParaExcluir . "'";
        DB::Exec($sqlDeletaTemaPrincipal);
    }
}

